import{_ as n}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as d,a as o,b as e,d as a,e as r,w as i,r as l,o as h}from"./app-D7aqq2EL.js";const c={},u={class:"hint-container tip"};function g(p,t){const s=l("RouteLink");return h(),d("div",null,[t[10]||(t[10]=o('<h1 id="source-path-analysis" tabindex="-1"><a class="header-anchor" href="#source-path-analysis"><span>Source &amp; Path Analysis</span></a></h1><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview"><span>Overview</span></a></h2><p>Source &amp; Path Analysis rolls up access logs <strong>per day</strong> and presents the traffic from two complementary angles:</p><ul><li><strong>Behaviour - who is hitting you</strong>: per source (IP), showing requests, blocks, backend 4xx, how many distinct paths it touched, and how many User-Agents it used.</li><li><strong>Target - what is being hit</strong>: per path template, showing requests, blocks, how many distinct sources hit it, and which rule it triggered most.</li></ul><p>Both tables come from the same daily rollup with a different grouping dimension, so the two angles always agree with each other.</p>',5)),e("div",u,[t[5]||(t[5]=e("p",{class:"hint-container-title"},"How this differs from the access log",-1)),e("p",null,[t[1]||(t[1]=a("This page is a ",-1)),t[2]||(t[2]=e("strong",null,"daily",-1)),t[3]||(t[3]=a(' rollup with no timestamps. It answers "who was most active yesterday, which endpoint got probed the most". For the content of one individual request, or times down to the second, use the ',-1)),r(s,{to:"/en/guide/VisitLog.html"},{default:i(()=>[...t[0]||(t[0]=[a("Access Log",-1)])]),_:1}),t[4]||(t[4]=a(".",-1))])]),t[11]||(t[11]=e("p",null,[a("The rollups are accumulated as logs are written and "),e("strong",null,"never scan the raw log tables"),a(', so this page still has complete data even when the access log mode on the access log page is set to "Sampled" or "Security events only".')],-1)),t[12]||(t[12]=e("h2",{id:"prerequisites",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#prerequisites"},[e("span",null,"Prerequisites")])],-1)),e("ul",null,[t[9]||(t[9]=e("li",null,[a("Rollups only accumulate from traffic "),e("strong",null,"after this feature is in place"),a("; historical logs are not backfilled. The page is empty right after upgrading and gives a complete picture of yesterday once a full day has passed.")],-1)),e("li",null,[t[7]||(t[7]=a('Plain requests silenced by an "exclude IP when logging" list write no log row and therefore never reach these rollups (see the log settings section of the ',-1)),r(s,{to:"/en/guide/VisitLog.html"},{default:i(()=>[...t[6]||(t[6]=[a("Access Log",-1)])]),_:1}),t[8]||(t[8]=a(").",-1))])]),t[13]||(t[13]=o('<h2 id="steps" tabindex="-1"><a class="header-anchor" href="#steps"><span>Steps</span></a></h2><h3 id="_1-choose-the-scope" tabindex="-1"><a class="header-anchor" href="#_1-choose-the-scope"><span>1. Choose the scope</span></a></h3><p>The query bar at the top holds, in order:</p><ol><li><strong>Date</strong> - which day to look at, today by default.</li><li><strong>Site</strong> - leave empty for all sites, or pick one.</li><li><strong>Top</strong> - how many rows each table returns: 20 / 50 / 100.</li><li>Click <strong>Search</strong> to refresh.</li></ol><h3 id="_2-adjust-the-thresholds-optional" tabindex="-1"><a class="header-anchor" href="#_2-adjust-the-thresholds-optional"><span>2. Adjust the thresholds (optional)</span></a></h3><p>The second card holds two verdict thresholds; changing either recalculates the page immediately:</p><ul><li><strong>Distinct paths &gt;= N flags a directory scan</strong> - a source that touched more than N distinct paths in one day gets the &quot;Directory scan&quot; tag.</li><li><strong>User agents &gt;= N flags UA rotation</strong> - a source that used more than N User-Agents gets the &quot;UA rotation&quot; tag.</li></ul><p><strong>Save as default</strong> stores the current two numbers so they are used next time you open the page.</p><div class="hint-container warning"><p class="hint-container-title">Thresholds only affect what you see</p><p>These two numbers change the tags and filtering on this page only. They <strong>never change how the WAF blocks traffic</strong> and never create a ban. To actually block, use the block action in the table, or configure a rule in the relevant protection settings.</p></div><h3 id="_3-read-the-summary-cards" tabindex="-1"><a class="header-anchor" href="#_3-read-the-summary-cards"><span>3. Read the summary cards</span></a></h3><table><thead><tr><th>Card</th><th>Meaning</th></tr></thead><tbody><tr><td>Sources</td><td>Distinct IPs seen that day.</td></tr><tr><td>Path templates</td><td>Distinct paths after normalization.</td></tr><tr><td>Likely directory scan</td><td>Number of sources whose distinct-path count reached the threshold. <strong>Click to filter</strong> the tables below to just those sources.</td></tr><tr><td>Likely UA rotation</td><td>Number of sources whose User-Agent count reached the threshold. <strong>Click to filter.</strong></td></tr></tbody></table><p>Clicking the selected card again clears the filter.</p><h3 id="_4-behaviour-who-is-hitting-you" tabindex="-1"><a class="header-anchor" href="#_4-behaviour-who-is-hitting-you"><span>4. Behaviour: who is hitting you</span></a></h3><p>The table is sorted by distinct paths descending, so scanners surface first. Numbers past a threshold are highlighted, and the Verdict column shows one of &quot;Directory scan&quot;, &quot;UA rotation&quot; or &quot;Has blocks&quot;.</p><ul><li>Click a <strong>Source</strong> to open the source detail drawer.</li><li>The action column offers <strong>Block</strong> and <strong>Allowlist</strong> for that IP on the spot.</li></ul><h3 id="_5-target-what-is-being-hit" tabindex="-1"><a class="header-anchor" href="#_5-target-what-is-being-hit"><span>5. Target: what is being hit</span></a></h3><p>Grouped by path template. Paths are <strong>normalized</strong> before being rolled up - numeric segments, UUIDs and hex strings become placeholders, so <code>/user/1001</code> and <code>/user/1002</code> collapse into one row.</p><p>Each site is capped at 5000 templates per day, and everything beyond that lands in a single <code>{overflow}</code> row, tagged &quot;template cap reached&quot;. Seeing it usually means the site is being scanned with a flood of random paths.</p><h3 id="_6-drill-down" tabindex="-1"><a class="header-anchor" href="#_6-drill-down"><span>6. Drill down</span></a></h3><p>Clicking a source or path opens a drawer with that object&#39;s detail for the day:</p><ul><li><strong>Source detail</strong>: the paths it touched, the User-Agents it used, the sites it hit, plus actions (Block / Allowlist / Raw logs).</li><li><strong>Path detail</strong>: who hit it, and which rules were triggered.</li></ul><h3 id="_7-block-or-allowlist" tabindex="-1"><a class="header-anchor" href="#_7-block-or-allowlist"><span>7. Block or allowlist</span></a></h3><p><strong>Block</strong> and <strong>Allowlist</strong> open the shared IP disposal dialog. You <strong>must pick a site</strong> - SamWaf&#39;s block and allow lists apply per site, and an IP aggregated across sites needs you to say which site it belongs under. The &quot;Sites it hit&quot; table in the source drawer is there to make that choice.</p><h2 id="field-reference" tabindex="-1"><a class="header-anchor" href="#field-reference"><span>Field Reference</span></a></h2><h3 id="query-conditions" tabindex="-1"><a class="header-anchor" href="#query-conditions"><span>Query conditions</span></a></h3><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Date</td><td>Which day&#39;s rollup to show; daily granularity.</td></tr><tr><td>Site</td><td>Filter by site; empty means all sites.</td></tr><tr><td>Top</td><td>Maximum rows per table (20 / 50 / 100).</td></tr><tr><td>Distinct paths &gt;=</td><td>Threshold for the &quot;Directory scan&quot; verdict; can be saved as the default.</td></tr><tr><td>User agents &gt;=</td><td>Threshold for the &quot;UA rotation&quot; verdict; can be saved as the default.</td></tr></tbody></table><h3 id="behaviour-columns" tabindex="-1"><a class="header-anchor" href="#behaviour-columns"><span>Behaviour columns</span></a></h3><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Source</td><td>Source identifier, currently the source IP. Click to drill down.</td></tr><tr><td>Requests</td><td>Total requests from that source that day.</td></tr><tr><td>Blocked</td><td>How many of them the WAF blocked.</td></tr><tr><td>Backend 4xx</td><td>How many got a 4xx from the backend; high when probing paths that do not exist.</td></tr><tr><td>Distinct paths</td><td>How many distinct path templates it touched; highlighted at the threshold.</td></tr><tr><td>UAs</td><td>How many distinct User-Agents it used; highlighted at the threshold.</td></tr><tr><td>Verdict</td><td>Directory scan / UA rotation / Has blocks, derived from the thresholds and the block count.</td></tr><tr><td>Actions</td><td>Block / Allowlist.</td></tr></tbody></table><h3 id="target-columns" tabindex="-1"><a class="header-anchor" href="#target-columns"><span>Target columns</span></a></h3><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Path template</td><td>The normalized path. <code>{overflow}</code> is the catch-all row once the daily template cap is reached.</td></tr><tr><td>Requests</td><td>Total requests to that path that day.</td></tr><tr><td>Blocked</td><td>How many of them were blocked.</td></tr><tr><td>Backend 4xx</td><td>How many got a 4xx from the backend.</td></tr><tr><td>Distinct sources</td><td>How many different IPs requested it.</td></tr><tr><td>Top rule</td><td>The rule triggered most often on that path.</td></tr></tbody></table><h2 id="faq" tabindex="-1"><a class="header-anchor" href="#faq"><span>FAQ</span></a></h2><ul><li><strong>The numbers here do not match the access log page.</strong> This page is a daily rollup (distinct counts are computed at read time) while the access log is request by request, so the two measure different things. Also, plain requests silenced by an &quot;exclude IP when logging&quot; list write no log row and never reach the rollups, while their traffic bytes are still counted in traffic statistics.</li><li><strong>Why did my path turn into something like <code>/user/{num}</code>?</strong> That is normalization. Without it, URLs carrying IDs would fill the table and no pattern would be visible.</li><li><strong>Do I need to act on <code>{overflow}</code>?</strong> It means the site reached the 5000 path-template cap for that day, usually because it is being scanned with random paths. Use the behaviour angle to find the source, then decide.</li><li><strong>Does a &quot;Directory scan&quot; verdict ban anything automatically?</strong> No. Verdicts are labels on this page only; acting on them is your call via Block.</li><li><strong>The page is empty right after upgrading.</strong> Rollups start accumulating only from traffic after the upgrade; historical logs are not backfilled, so give it a full day.</li></ul>',32))])}const y=n(c,[["render",g]]),b=JSON.parse('{"path":"/en/guide/SourcePathAnalysis.html","title":"Source & Path Analysis","lang":"en-US","frontmatter":{},"git":{"createdTime":1791512044000,"updatedTime":1791512044000,"contributors":[{"name":"samwaf","username":"samwaf","email":"samwafgo@gmail.com","commits":1,"url":"https://github.com/samwaf"}]},"readingTime":{"minutes":3.89,"words":1168},"filePathRelative":"en/guide/SourcePathAnalysis.md"}');export{y as comp,b as data};
